    "active": true,
    "isArchived": false,
    "nodes": [
      {
        "id": "schedule-trigger",
        "name": "Daily 6AM ET Trigger",
        "type": "n8n-nodes-base.scheduleTrigger",
        "typeVersion": 1.3,
        "position": [
          0,
          400
