          200
        ],
        "parameters": {}
      },
      {
        "id": "error-trigger",
        "name": "Error Trigger",
        "type": "n8n-nodes-base.errorTrigger",
        "typeVersion": 1,
        "position": [
          0,
          800
        ],
        "parameters": {}
      },
      {
        "id": "post-error-alert",
        "name": "POST Tournament Error Alert",
        "type": "n8n-nodes-base.httpRequest",
        "typeVersion": 4.4,
        "position": [
          260,
          800
        ],
        "parameters": {
          "method": "POST",
          "url": "http://host.docker.internal:4000/api/sse/broadcast",
          "sendBody": true,
          "specifyBody": "json",
          "jsonBody": "={{ JSON.stringify({ title: 'Workflow Error: Strategy Tournament', message: $json.execution ? (typeof $json.execution.error === 'object' ? $json.execution.error.message : String($json.execution.error)) : 'Unknown error', severity: 'critical', data: { workflow: 'Strategy Tournament', executionId: $json.execution ? String($json.execution.id) : 'N/A', timestamp: new Date().toISOString() } }) }}",
          "options": {
            "timeout": 15000
          }
        },
        "onError": "continueRegularOutput",
        "retryOnFail": true,
        "maxTries": 2
      }
    ],
    "connections": {
      "Daily 6AM ET Trigger": {
        "main": [
          [
            {
              "node": "Proposer (qwen3)",
              "type": "main",
